from flask import Blueprint, request, jsonify
from app.models.problem import Problem

def problem_blueprint():
    problem_bp = Blueprint('problem', __name__)

    @problem_bp.route('/problems', methods=['GET'])
    def get_problems():
        try:
            problems = Problem.query.all()
            return jsonify([problem.to_dict() for problem in problems]), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @problem_bp.route('/problems', methods=['POST'])
    def create_problem():
        try:
            data = request.get_json()
            if not data:
                return jsonify({'error': 'Invalid input'}), 400

            new_problem = Problem(**data)
            new_problem.save()
            return jsonify(new_problem.to_dict()), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        try:
            data = request.get_json()
            if not data:
                return jsonify({'error': 'Invalid input'}), 400

            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            for key, value in data.items():
                setattr(problem, key, value)
            problem.save()
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            problem.delete()
            return jsonify({'message': 'Problem deleted successfully'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    return problem_bp

from flask import Blueprint, request, jsonify
from app.models.user import User

def user_blueprint():
    user_bp = Blueprint('user', __name__)

    @user_bp.route('/users', methods=['GET'])
    def get_users():
        # Normally, you would interact with the database here, but since there's no database layer, we simulate a response
        mock_users = [
            {"id": 1, "name": "Alice", "email": "alice@example.com"},
            {"id": 2, "name": "Bob", "email": "bob@example.com"}
        ]
        return jsonify(mock_users), 200

    @user_bp.route('/users', methods=['POST'])
    def create_user():
        data = request.get_json()
        if not data or not all(key in data for key in ['name', 'email']):
            return jsonify({"error": "Invalid input"}), 400

        # Simulate a new user creation
        new_user = {
            "id": 3,  # Normally generated by the database
            "name": data['name'],
            "email": data['email']
        }
        return jsonify(new_user), 201

    @user_bp.route('/users/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        # Simulate fetching a single user
        if user_id == 1:
            user = {"id": 1, "name": "Alice", "email": "alice@example.com"}
        elif user_id == 2:
            user = {"id": 2, "name": "Bob", "email": "bob@example.com"}
        else:
            return jsonify({"error": "User not found"}), 404

        return jsonify(user), 200

    return user_bp

from flask import Blueprint, request, jsonify
from app.models.solution import Solution

def solution_blueprint():
    blueprint = Blueprint('solution', __name__)

    @blueprint.route('/submit', methods=['POST'])
    def submit_solution():
        try:
            data = request.get_json()
            user_id = data.get('user_id')
            problem_id = data.get('problem_id')
            code = data.get('code')

            if not user_id or not problem_id or not code:
                return jsonify({'error': 'Missing required fields'}), 400

            solution = Solution(user_id=user_id, problem_id=problem_id, code=code)
            solution.save()

            return jsonify({'message': 'Solution submitted successfully'}), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/solutions', methods=['GET'])
    def get_solutions():
        try:
            solutions = Solution.query.all()
            result = [solution.to_dict() for solution in solutions]
            return jsonify(result), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/solution/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        try:
            solution = Solution.query.get(solution_id)
            if not solution:
                return jsonify({'error': 'Solution not found'}), 404

            return jsonify(solution.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    return blueprint
